"use client"

import { useRef } from "react"
import { ChevronLeft, ChevronRight, Clock, Users, MapPin } from "lucide-react"
import { Button } from "@/components/ui/button"
import type { Event } from "@/lib/events-data"

interface EventsCarouselProps {
  events: Event[]
  onEventClick: (event: Event) => void
}

export function EventsCarousel({ events, onEventClick }: EventsCarouselProps) {
  const containerRef = useRef<HTMLDivElement>(null)

  const scroll = (direction: "left" | "right") => {
    if (containerRef.current) {
      const scrollAmount = containerRef.current.clientWidth * 0.8
      containerRef.current.scrollBy({
        left: direction === "left" ? -scrollAmount : scrollAmount,
        behavior: "smooth",
      })
    }
  }

  const getLevel = (event: Event) => {
    const attendancePercent = Math.round((event.currentAttendees / event.maxAttendees) * 100)
    if (attendancePercent >= 90) return "Популярное"
    if (attendancePercent >= 70) return "Востребованное"
    return "Доступное"
  }

  if (events.length === 0) return null

  return (
    <div className="relative">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-2xl font-bold text-foreground">Рекомендуем</h2>
          <p className="text-muted-foreground mt-1">Популярные мероприятия недели</p>
        </div>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="icon"
            onClick={() => scroll("left")}
            className="rounded-full border-border hover:bg-accent bg-transparent"
          >
            <ChevronLeft className="w-5 h-5" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            onClick={() => scroll("right")}
            className="rounded-full border-border hover:bg-accent"
          >
            <ChevronRight className="w-5 h-5" />
          </Button>
        </div>
      </div>

      {/* Carousel */}
      <div
        ref={containerRef}
        className="flex gap-4 overflow-x-auto scroll-smooth pb-4 scrollbar-hide"
        style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
      >
        {events.map((event) => (
          <div
            key={event.id}
            className="flex-shrink-0 w-[calc((100%-64px)/5)] min-w-[200px] cursor-pointer group"
            onClick={() => onEventClick(event)}
          >
            <div className="relative aspect-[3/4] rounded-2xl overflow-hidden">
              {/* Background Image */}
              <img
                src={event.image || "/placeholder.svg"}
                alt={event.title}
                className="absolute inset-0 w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
              />

              {/* Dark Gradient Overlay */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-black/20" />

              {/* Content */}
              <div className="absolute inset-0 flex flex-col justify-end p-4">
                {/* Title */}
                <h3 className="text-white text-lg font-bold mb-2 line-clamp-2">
                  {event.title}
                </h3>

                {/* Info Items */}
                <div className="space-y-1 text-white/90 text-xs mb-3">
                  <div className="flex items-center gap-2">
                    <Clock className="w-3.5 h-3.5 text-white/70" />
                    <span>1 день</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Users className="w-3.5 h-3.5 text-white/70" />
                    <span>{getLevel(event)}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <MapPin className="w-3.5 h-3.5 text-white/70" />
                      <span className="truncate max-w-[80px]">{event.location}</span>
                    </div>
                    <span className="font-semibold text-white text-xs">
                      {event.isFree ? "Бесплатно" : `${event.price.toLocaleString("ru-RU")} руб.`}
                    </span>
                  </div>
                </div>

                {/* Button */}
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full bg-transparent border-white/30 text-white hover:bg-white hover:text-black transition-all duration-300 text-xs"
                  onClick={(e) => {
                    e.stopPropagation()
                    onEventClick(event)
                  }}
                >
                  Узнать подробнее
                </Button>
              </div>
            </div>
          </div>
        ))}
      </div>

    </div>
  )
}
